<?php
namespace App\Http\Controllers;
use App\PaymentMethod;use App\Services\PaymentMethodAvailabilityService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Redirect;use Illuminate\Support\Facades\Validator;use Illuminate\Validation\Rule;
class PaymentMethodAdminController extends Controller{
 private $types=['cash_on_delivery','mobile_financial_service','payment_gateway','bank_transfer','qr_payment','card_payment','manual_payment','custom'];private $modes=['api','manual','redirect','hosted_checkout','offline'];
 public function index(Request $r,PaymentMethodAvailabilityService $availability){$methods=PaymentMethod::with('emiPlans')->withCount('transactions')->orderBy('display_order')->get();$methods->each(function($m)use($availability){$m->health_issues=$availability->health($m);});$transactions=DB::table('payment_transactions as t')->join('payment_methods as m','m.id','=','t.payment_method_id')->select('t.*','m.name as method_name')->latest('t.id')->limit(20)->get();$zones=DB::table('delivery_zones')->where('is_active',1)->orderBy('display_order')->get();return view('admin.admin-pages.payment-methods',compact('methods','transactions','zones'));}
 public function edit($id){$method=PaymentMethod::with('emiPlans')->findOrFail($id);$zones=DB::table('delivery_zones')->where('is_active',1)->orderBy('display_order')->get();return view('admin.admin-pages.payment-method-edit',compact('method','zones'));}
 public function save(Request $r){$id=$r->integer('id')?:null;$method=$id?PaymentMethod::findOrFail($id):null;$v=Validator::make($r->all(),['name'=>'required|string|max:150','code'=>['required','regex:/^[a-z0-9_\-]+$/','max:50',Rule::unique('payment_methods','code')->ignore($id)],'method_type'=>['required',Rule::in($this->types)],'provider'=>'nullable|string|max:100','integration_mode'=>['required',Rule::in($this->modes)],'environment'=>'required|in:sandbox,live','customer_label'=>'required|string|max:150','description'=>'nullable|string|max:2000','short_instruction'=>'nullable|string|max:500','detailed_instruction'=>'nullable|string|max:4000','logo'=>'nullable|image|mimes:png,jpg,jpeg,webp|max:1024','minimum_order_amount'=>'nullable|numeric|min:0','maximum_order_amount'=>'nullable|numeric|min:0|gte:minimum_order_amount','charge_type'=>'required|in:fixed,percentage,fixed_plus_percentage','charge_value'=>'nullable|numeric|min:0','charge_payer'=>'required|in:customer,merchant,included','minimum_charge'=>'nullable|numeric|min:0','maximum_charge'=>'nullable|numeric|min:0|gte:minimum_charge','free_above_amount'=>'nullable|numeric|min:0','display_order'=>'required|integer|min:0','merchant_number'=>'nullable|string|max:100','account_type'=>'nullable|in:merchant,personal,agent,other','payment_verification_mode'=>'required|in:automatic,manual','bank_details'=>'nullable|string|max:4000','qr_type'=>'nullable|in:static,provider_generated,gateway_redirect,bangla_qr,custom','available_from'=>'nullable|date','available_until'=>'nullable|date|after_or_equal:available_from','success_callback_url'=>'nullable|string|max:500','failure_callback_url'=>'nullable|string|max:500','cancel_callback_url'=>'nullable|string|max:500','webhook_url'=>'nullable|string|max:500']);$v->after(function($v)use($r){foreach(['success_callback_url','failure_callback_url','cancel_callback_url','webhook_url']as $key)if($r->filled($key)&&!$this->safeUrl($r->input($key)))$v->errors()->add($key,'Use an internal path or HTTPS URL.');if($r->method_type==='mobile_financial_service'&&$r->integration_mode==='manual'&&!$r->filled('merchant_number'))$v->errors()->add('merchant_number','A merchant number is required for manual MFS.');if($r->method_type==='bank_transfer'&&!$r->filled('bank_details'))$v->errors()->add('bank_details','Bank details are required.');});$v->validate();$data=$r->only(['name','method_type','provider','integration_mode','environment','customer_label','description','short_instruction','detailed_instruction','icon','charge_type','charge_value','charge_payer','minimum_charge','maximum_charge','free_above_amount','merchant_number','account_type','payment_verification_mode','bank_details','qr_type','available_from','available_until','success_callback_url','failure_callback_url','cancel_callback_url','webhook_url']);$data['code']=str_slug($r->code,'_');$data['type']=$this->legacyType($r->method_type);foreach(['minimum_order_amount','maximum_order_amount']as $k)$data[$k]=$r->filled($k)?$r->input($k):null;$data['display_order']=(int)$r->display_order;foreach(['supports_emi','is_active','show_at_checkout','allow_sandbox_at_checkout','charge_enabled','display_charge_at_checkout','require_transaction_id','require_sender_number','require_payment_screenshot']as $k)$data[$k]=$r->boolean($k);$data['instructions']=$data['short_instruction']??null;$data['availability_rules']=['allowed_shipping_zones'=>array_values(array_filter((array)$r->input('allowed_shipping_zones',[]))),'blocked_shipping_zones'=>array_values(array_filter((array)$r->input('blocked_shipping_zones',[])))];if($r->hasFile('logo')){$path='asset/front-end/img/payments';if(!is_dir(public_path($path)))mkdir(public_path($path),0755,true);$name='payment-'.str_random(12).'.'.$r->file('logo')->extension();$r->file('logo')->move(public_path($path),$name);$data['logo_path']=$path.'/'.$name;}if($r->filled('credential_value')){$credentials=[];if($method&&$method->credentials)try{$credentials=json_decode(Crypt::decryptString($method->credentials),true)?:[];}catch(\Throwable $e){}$credentials[$r->input('credential_key','api_secret')]=$r->credential_value;$data['credentials']=Crypt::encryptString(json_encode($credentials));$data['credentials_updated_at']=now();}$data['updated_at']=now();if($method)$method->update($data);else{$data['created_at']=now();PaymentMethod::create($data);}Cache::forget('active_payment_methods');$this->audit($method?'Payment Method Updated':'Payment Method Created',['code'=>$data['code']]);return Redirect::to('/payment-methods')->with('message','Payment method saved successfully.');}
 public function toggle($id){$m=PaymentMethod::findOrFail($id);$m->update(['is_active'=>!$m->is_active]);Cache::forget('active_payment_methods');$this->audit('Payment Method Status Updated',['id'=>$m->id,'active'=>$m->is_active]);return back()->with('message',$m->is_active?'Payment method enabled.':'Payment method disabled.');}
 public function duplicate($id){$m=PaymentMethod::findOrFail($id);$copy=$m->replicate(['credentials','credentials_updated_at','connection_status','last_connection_test_at','last_connection_message']);$copy->name.=' Copy';$copy->code=$m->code.'_copy_'.strtolower(str_random(4));$copy->is_active=false;$copy->environment='sandbox';$copy->save();return back()->with('message','Payment method duplicated in Sandbox mode.');}
 public function delete($id){$m=PaymentMethod::findOrFail($id);if(DB::table('orders')->where('payment_method_id',$id)->exists()||$m->transactions()->exists()){$m->update(['is_active'=>0,'show_at_checkout'=>0,'is_archived'=>1]);return back()->with('message','Method has transaction history and was archived instead of deleted.');}$m->delete();return back()->with('message','Payment method deleted.');}
 public function reorder(Request $r){$this->validate($r,['order'=>'required|array','order.*'=>'integer|exists:payment_methods,id']);foreach($r->order as $i=>$id)PaymentMethod::where('id',$id)->update(['display_order'=>$i]);Cache::forget('active_payment_methods');return response()->json(['message'=>'Payment order updated.']);}
 public function preview($id,PaymentMethodAvailabilityService $a){$m=PaymentMethod::findOrFail($id);return response()->json(['name'=>$m->publicName(),'instruction'=>$m->short_instruction,'provider'=>$m->provider,'environment'=>$m->environment,'charge'=>$a->charge($m,10000),'issues'=>$a->health($m)]);}
 public function test($id){$m=PaymentMethod::findOrFail($id);if(!$m->isOnline()){$m->update(['connection_status'=>'not_applicable','last_connection_test_at'=>now(),'last_connection_message'=>'Manual and offline methods do not require a gateway connection.']);return back()->with('message','No gateway connection is required for this manual/offline method.');}$m->update(['connection_status'=>'configuration_required','last_connection_test_at'=>now(),'last_connection_message'=>'No verified provider adapter is installed.']);return back()->with('exception','Integration not configured. Add a verified provider adapter and merchant credentials before live activation.');}
 public function verifyTransaction(Request $r,$id){$this->validate($r,['decision'=>'required|in:verified,rejected','reason'=>'nullable|string|max:500']);DB::transaction(function()use($r,$id){$t=DB::table('payment_transactions')->where('id',$id)->lockForUpdate()->first();abort_unless($t,404);abort_if(!in_array($t->status,['pending','awaiting_verification'],true),422,'This transaction has already been reviewed.');DB::table('payment_transactions')->where('id',$id)->update(['status'=>$r->decision,'failure_reason'=>$r->decision==='rejected'?trim((string)$r->reason):null,'verified_by'=>session('admin_id'),'verified_at'=>now(),'updated_at'=>now()]);if($t->order_id)DB::table('orders')->where('id',$t->order_id)->update(['payment_status'=>$r->decision,'updated_at'=>now()]);});$this->audit('Manual Payment '.$r->decision,['transaction_id'=>$id]);return back()->with('message',$r->decision==='verified'?'Payment verified successfully.':'Payment rejected.');}
 private function legacyType($t){return ['cash_on_delivery'=>'cash','bank_transfer'=>'bank','card_payment'=>'card','payment_gateway'=>'card','mobile_financial_service'=>'mobile'][$t]??'offline';}private function safeUrl($u){return strpos($u,'/')===0&&strpos($u,'//')!==0||(filter_var($u,FILTER_VALIDATE_URL)&&strtolower(parse_url($u,PHP_URL_SCHEME))==='https');}private function audit($action,$details){if(!\Schema::hasTable('admin_activity_logs'))return;DB::table('admin_activity_logs')->insert(['admin_id'=>session('admin_id'),'admin_name'=>session('admin_name'),'action'=>$action,'method'=>request()->method(),'path'=>request()->path(),'ip_hash'=>hash_hmac('sha256',(string)request()->ip(),config('app.key')),'details'=>json_encode($details),'created_at'=>now()]);}}
